"""Admission (capacity + deficient cut) and schedule compilation."""
from cutcheck import find_deficient_cut
from maxflow import Dinic


# ------------------------------------------------------------------ admission
def capacity_denial(svc, pid, s, e, env):
    """Return a capacity denial certificate, or None if the envelope fits."""
    ticks = set([s])
    for b in svc.bookings.values():
        if b.live and s < b.s < e:
            ticks.add(b.s)
    for t in sorted(ticks):
        for l, bl in env.items():
            used = svc.used_at(l, t)
            if used + bl > svc.caps[l]:
                return {'status': 'denied', 'id': pid, 'rev': svc.rev,
                        'kind': 'capacity', 'link': l, 'time': t,
                        'used': used + bl, 'capacity': svc.caps[l]}
    return None


def compile_prepare(svc, pid, s, e, period, parts, env):
    cap_cert = capacity_denial(svc, pid, s, e, env)
    if cap_cert is not None:
        return cap_cert
    caps = [period * env.get(l, 0) for l in range(len(svc.links))]
    r = dict(parts)
    cut = find_deficient_cut(svc.n, svc.links, caps, parts, r)
    if cut is not None:
        return {'status': 'denied', 'id': pid, 'rev': svc.rev,
                'kind': 'cut', 'cut': cut}
    plan = build_plan(svc.n, svc.links, caps, parts, r)
    if plan is None:
        # Construction could not realise a feasible instance: fall back to a
        # direct all-pairs construction attempt.
        plan = build_plan_flat(svc.n, svc.links, caps, parts, r)
    if plan is None:
        return {'status': 'denied', 'id': pid, 'rev': svc.rev,
                'kind': 'cut', 'cut': _fallback_cut(svc.n, svc.links, caps,
                                                    parts, r)}
    return {'status': 'prepared', 'id': pid, 'rev': svc.rev, 'plan': plan}


def _fallback_cut(n, links, caps, parts, r):
    cut = find_deficient_cut(n, links, caps, parts, r)
    return cut if cut is not None else [parts[0][0]]


# ------------------------------------------------------------------ hierarchy
def _mincut_side(vertices, links, caps, src, dst):
    """Partition `vertices` into (side containing src, rest) by a min cut."""
    idx = {v: i for i, v in enumerate(vertices)}
    g = Dinic(len(vertices))
    for l, (u, v) in enumerate(links):
        if u in idx and v in idx and caps[l] > 0:
            g.add(idx[u], idx[v], caps[l])
            g.add(idx[v], idx[u], caps[l])
    g.maxflow(idx[src], idx[dst])
    mark = g.reachable(idx[src])
    A = set([v for v in vertices if mark[idx[v]]])
    B = set([v for v in vertices if not mark[idx[v]]])
    return A, B


class Node(object):
    __slots__ = ('parts', 'region', 'dem', 'u', 'w', 'children', 'leaf')

    def __init__(self):
        self.parts = []
        self.region = set()
        self.dem = 0
        self.u = None
        self.w = None
        self.children = None
        self.leaf = None


def build_hierarchy(vertices, parts, links, caps):
    node = Node()
    node.region = set(vertices)
    node.parts = list(parts)
    node.dem = sum(rv for (_v, rv) in parts)
    if len(parts) == 1:
        node.leaf = parts[0][0]
        return node
    # choose a pair of participants with the smallest connectivity
    best = None
    p0 = parts[0][0]
    cands = [v for (v, _rv) in parts]
    for q in cands:
        if q == p0:
            continue
        A, B = _mincut_side(list(vertices), links, caps, p0, q)
        if p0 in B:
            A, B = B, A
        pa = [x for x in parts if x[0] in A]
        pb = [x for x in parts if x[0] in B]
        if not pa or not pb:
            continue
        balance = abs(len(pa) - len(pb))
        if best is None or balance < best[0]:
            best = (balance, A, B, pa, pb)
    if best is None:
        # degenerate: split arbitrarily
        half = len(parts) // 2
        pa = parts[:half]
        pb = parts[half:]
        A = set([x[0] for x in pa])
        B = set([x[0] for x in pb])
        best = (0, A, B, pa, pb)
    _bal, A, B, pa, pb = best
    ca = build_hierarchy(A, pa, links, caps)
    cb = build_hierarchy(B, pb, links, caps)
    node.children = (ca, cb)
    return node


# ------------------------------------------------------------------ routing
class ArcFlow(object):
    def __init__(self, n, links, caps):
        self.n = n
        self.links = links
        self.res = list(caps)
        self.head = [links[a // 2][0] if a % 2 == 0 else links[a // 2][1]
                     for a in range(2 * len(links))]
        self.tail = [links[a // 2][1] if a % 2 == 0 else links[a // 2][0]
                     for a in range(2 * len(links))]

    def route(self, src, dst, amount, region):
        """Route `amount` units from src to dst using arcs inside `region`.

        Returns a list of (arc, amount) or None on failure.
        """
        if amount == 0:
            return []
        verts = [v for v in region]
        idx = {v: i for i, v in enumerate(verts)}
        g = Dinic(len(verts) + 2)
        S = len(verts)
        T = S + 1
        arcs = []
        for a in range(len(self.res)):
            if self.res[a] > 0 and self.tail[a] in idx and self.head[a] in idx:
                arcs.append((a, g.add(idx[self.tail[a]], idx[self.head[a]],
                                      self.res[a])))
        g.add(S, idx[src], amount)
        g.add(idx[dst], T, amount)
        got = g.maxflow(S, T)
        if got != amount:
            return None
        out = []
        for (a, i) in arcs:
            f = self.res[a] - g.cap[i]
            if f > 0:
                out.append((a, f))
                self.res[a] -= f
        return out


# ------------------------------------------------------------------ plan build
def build_plan(n, links, caps, parts, r):
    D = sum(r.values())
    if D <= 0:
        return None
    root = build_hierarchy(list(range(n)), parts, links, caps)
    flow = ArcFlow(n, links, caps)

    # pick (u,w) for every internal node, top-down, routing as we go
    edges = []   # (u, w, amount_u_to_w, amount_w_to_u, node)

    def walk(node):
        if node.children is None:
            return True
        ca, cb = node.children
        if not walk(ca) or not walk(cb):
            return False
        ra = ca.dem
        rb = cb.dem
        cands_a = [ca] + _subnodes(ca)
