        lb = _leaves(cb)
        if not la or not lb:
            return False
        region = node.region
        chosen = None
        for u in la:
            for w in lb:
                if ra > 0:
                    f1 = flow.route(u, w, ra, region)
                    if f1 is None:
                        continue
