                        continue
                else:
                    f2 = []
                chosen = (u, w, f1, f2)
                break
            if chosen:
                break
        if chosen is None:
            return False
        u, w, f1, f2 = chosen
        node.u = u
        node.w = w
        edges.append((u, w, ra, rb, f1, f2))
        return True

    if not walk(root):
        return None

    # ---- logical trees: hierarchy tree oriented away from each root
    tree_edges = []   # (u, w) with L(u,w)=dem(side of u), L(w,u)=dem(other)
    for (u, w, ra, rb, _f1, _f2) in edges:
        tree_edges.append((u, w, ra, rb))

    adj = {}
    for (u, w, ra, rb) in tree_edges:
        adj.setdefault(u, []).append((w, ra, rb))
        adj.setdefault(w, []).append((u, rb, ra))

    trees = []
    for (v, rv) in parts:
        if rv <= 0:
            continue
        # BFS from v over the hierarchy tree
        parent = {v: None}
        order = [v]
        edgelist = []
        qi = 0
