        if rb > 0:
            _emit_routes(w, u, rb, f2, routes, recipes, recipe_of)

    return {'trees': trees, 'routes': routes, 'recipes': recipes}


def _subnodes(node):
    out = []
    if node.children is None:
        return out
    for c in node.children:
        out.append(c)
        out.extend(_subnodes(c))
    return out


def _leaves(node):
    if node.children is None:
        return [node.leaf]
    out = []
    for c in node.children:
        out.extend(_leaves(c))
    return out


